#!/bin/bash
# Extracts tables from haproxy-quic/include/import/slz-tables.h
H="../../reference/haproxy-quic"
cat << 'RUST' > src/tables.rs
// Generated by gen_tables.sh from slz-tables.h
// DO NOT EDIT
RUST

awk '
/static const uint32_t len_fh/ { in_table = "LEN_FH"; print "pub static " in_table ": [u32; 259] = ["; next }
/static const uint32_t fh_dist_table/ { in_table = "FH_DIST_TABLE"; print "pub static " in_table ": [u32; 32768] = ["; next }
/static const uint32_t fixed_huff/ { in_table = "FIXED_HUFF"; print "pub static " in_table ": [u32; 288] = ["; next }
/static const uint32_t crc32_fast/ { in_table = "CRC32_FAST"; print "pub static " in_table ": [[u32; 256]; 4] = ["; next }
/static const uint32_t fh_dist_dec_table/ { in_table = 0; next }
/static const uint16_t fixed_huff_dec_table/ { in_table = 0; next }
in_table && /};/ { print "];\n"; in_table = 0; next }
in_table {
    if (in_table == "CRC32_FAST" && /{/) { print "    ["; next }
    if (in_table == "CRC32_FAST" && /},/) { print "    ],"; next }
    gsub(/\/\*.*\*\//, "");
    print $0
}
' $H/include/import/slz-tables.h >> src/tables.rs
